/**
 * The rules of the media player, with no React and no device in them, so every one can be tested.
 *
 * The player is one set of controls for video, sound and pictures, on iPhone, Android and the web.
 * Two things it remembers for every file, until the user changes them: Loop, and Rotation. Speed
 * and captions belong to the file being played and start fresh each time.
 *
 * This file is the source. Apps take a copy of the whole folder from Pearkit; change it here.
 */

/** How the player turns with the phone. Kept for every video until changed. */
export type RotationLock = 'auto' | 'portrait' | 'landscape';

export type PlayerSettings = {
  /** Play each file again when it ends. */
  loop: boolean;
  rotation: RotationLock;
};

export const DEFAULT_PLAYER_SETTINGS: PlayerSettings = { loop: false, rotation: 'auto' };

export const ROTATION_CHOICES: readonly { value: RotationLock; label: string }[] = [
  { value: 'auto', label: 'Auto' },
  { value: 'portrait', label: 'Portrait' },
  { value: 'landscape', label: 'Landscape' },
];

/** Read saved settings. Anything missing or unreadable falls back to the default for that one field. */
export function parsePlayerSettings(raw: string | null | undefined): PlayerSettings {
  if (!raw) return { ...DEFAULT_PLAYER_SETTINGS };
  let data: unknown;
  try {
    data = JSON.parse(raw);
  } catch {
    return { ...DEFAULT_PLAYER_SETTINGS };
  }
  if (!data || typeof data !== 'object') return { ...DEFAULT_PLAYER_SETTINGS };
  const obj = data as Record<string, unknown>;
  const rotation =
    obj.rotation === 'auto' || obj.rotation === 'portrait' || obj.rotation === 'landscape'
      ? obj.rotation
      : DEFAULT_PLAYER_SETTINGS.rotation;
  return { loop: obj.loop === true, rotation };
}

export function serializePlayerSettings(settings: PlayerSettings): string {
  return JSON.stringify({ loop: settings.loop === true, rotation: settings.rotation });
}

// ---------------------------------------------------------------------------
// Rotation
// ---------------------------------------------------------------------------

/** What is on screen. A picture has nothing to play: it gets Back, the title, Share and the swipes. */
export type PlayerKind = 'video' | 'audio' | 'image';

/**
 * What the screen may do while the player is up. `"portrait"` is also the answer once the player
 * has closed, so the rest of the app stays upright.
 *
 * - A video follows the Orientation choice.
 * - A picture turns with the device, so swiping from a sideways video to a photo does not flip
 *   the screen. It has no Orientation buttons of its own, so it is never held sideways; it does
 *   stay upright for someone who chose upright.
 * - Sound stays upright.
 */
export function screenRotationFor(
  open: boolean,
  kind: PlayerKind | null,
  rotation: RotationLock,
): RotationLock {
  if (!open) return 'portrait';
  if (kind === 'video') return rotation;
  if (kind === 'image') return rotation === 'portrait' ? 'portrait' : 'auto';
  return 'portrait';
}

/** The same answer in the words the iPhone window takes. */
export function windowOrientationsFor(lock: RotationLock): ('portrait' | 'landscape')[] {
  if (lock === 'portrait') return ['portrait'];
  if (lock === 'landscape') return ['landscape'];
  return ['portrait', 'landscape'];
}

export type Edges = { top: number; bottom: number; left: number; right: number };

/**
 * The parts of the screen to keep clear of, worked out from the upright reading. On its side the
 * camera cut-out moves to one of the short edges; which one depends on the way the phone was
 * turned, so both are kept clear. The home bar stays along the bottom.
 */
export function playerEdges(upright: Edges, sideways: boolean): Edges {
  const clean = (n: number) => (Number.isFinite(n) && n > 0 ? n : 0);
  const top = clean(upright.top);
  const bottom = clean(upright.bottom);
  const left = clean(upright.left);
  const right = clean(upright.right);
  if (!sideways) return { top, bottom, left, right };
  // An iPhone gives the upright reading (cut-out at the top); Android gives a live one (cut-out
  // already at a side). The largest of the three is the cut-out either way.
  const side = Math.max(top, left, right);
  return { top: 0, bottom: Math.min(bottom, 21), left: side, right: side };
}

// ---------------------------------------------------------------------------
// Position
// ---------------------------------------------------------------------------

export const JUMP_SECONDS = 15;

function finite(n: unknown): number {
  const v = Number(n);
  return Number.isFinite(v) ? v : 0;
}

/** Where a jump lands: never before the start, never past the end. */
export function jumpTarget(position: number, delta: number, duration: number): number {
  const pos = Math.max(0, finite(position));
  const dur = Math.max(0, finite(duration));
  const next = pos + finite(delta);
  if (next <= 0) return 0;
  // Length not known yet: go where asked rather than refuse.
  if (dur <= 0) return next;
  return Math.min(dur, next);
}

/** Where a touch on the bar lands. `null` when the bar or the length is not known yet. */
export function barTarget(x: number, width: number, duration: number): number | null {
  const w = finite(width);
  const dur = finite(duration);
  if (w <= 0 || dur <= 0) return null;
  const fraction = Math.max(0, Math.min(1, finite(x) / w));
  return dur * fraction;
}

/** How full the bar is, 0 to 100. */
export function barPercent(position: number, duration: number): number {
  const dur = finite(duration);
  if (dur <= 0) return 0;
  return Math.max(0, Math.min(100, (finite(position) / dur) * 100));
}

/** Pressing Play at the end starts the file over; anywhere else it carries on. */
export function playStartsOver(position: number, duration: number): boolean {
  const dur = finite(duration);
  if (dur <= 0) return false;
  return finite(position) >= dur - 0.25;
}

// ---------------------------------------------------------------------------
// Speed
// ---------------------------------------------------------------------------

export const PLAYBACK_SPEEDS: readonly number[] = [0.5, 0.75, 1, 1.25, 1.5, 2];
export const NORMAL_SPEED = 1;

/** A speed the player offers: anything else becomes normal speed. */
export function validSpeed(rate: unknown): number {
  const r = Number(rate);
  return PLAYBACK_SPEEDS.includes(r) ? r : NORMAL_SPEED;
}

export function speedLabel(rate: number): string {
  return `${String(validSpeed(rate))}×`;
}

/**
 * The minus and plus buttons: one step along the list of speeds. At either end it stays put, and
 * `canStepSpeed` says so, so the button can be shown as spent.
 */
export function stepSpeed(rate: number, direction: 1 | -1): number {
  const at = PLAYBACK_SPEEDS.indexOf(validSpeed(rate));
  const next = Math.max(0, Math.min(PLAYBACK_SPEEDS.length - 1, at + (direction < 0 ? -1 : 1)));
  return PLAYBACK_SPEEDS[next] ?? NORMAL_SPEED;
}

export function canStepSpeed(rate: number, direction: 1 | -1): boolean {
  return stepSpeed(rate, direction) !== validSpeed(rate);
}

/** A position or a length as the bar shows it: 0:07, 12:40, 1:02:03. */
export function clockText(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) return '0:00';
  const total = Math.floor(seconds);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const ss = String(total % 60).padStart(2, '0');
  if (h > 0) return `${h}:${String(m).padStart(2, '0')}:${ss}`;
  return `${m}:${ss}`;
}

// ---------------------------------------------------------------------------
// Captions
