export type CaptionTrack = { id?: string | null; language?: string | null; label?: string | null };
export type CaptionChoice = {
  key: string;
  /** The name in the list: "English", or "English (US)" when two tracks share a language. */
  label: string;
  /** The short form on the button: "EN", or "EN-US" when two tracks share a language. */
  short: string;
  index: number;
  selected: boolean;
};

const LANGUAGE_NAMES: Record<string, string> = {
  en: 'English',
  es: 'Spanish',
  fr: 'French',
  de: 'German',
  it: 'Italian',
  pt: 'Portuguese',
  nl: 'Dutch',
  ja: 'Japanese',
  ko: 'Korean',
  zh: 'Chinese',
  ru: 'Russian',
  ar: 'Arabic',
  hi: 'Hindi',
  pl: 'Polish',
  sv: 'Swedish',
  tr: 'Turkish',
  uk: 'Ukrainian',
  he: 'Hebrew',
  id: 'Indonesian',
  vi: 'Vietnamese',
  th: 'Thai',
  el: 'Greek',
  cs: 'Czech',
  da: 'Danish',
  fi: 'Finnish',
  no: 'Norwegian',
  ro: 'Romanian',
  hu: 'Hungarian',
};

/** Files often carry the three-letter form of a language; the button shows the two-letter one. */
const THREE_LETTER: Record<string, string> = {
  eng: 'en',
  spa: 'es',
  fra: 'fr',
  fre: 'fr',
  deu: 'de',
  ger: 'de',
  ita: 'it',
  por: 'pt',
  nld: 'nl',
  dut: 'nl',
  jpn: 'ja',
  kor: 'ko',
  zho: 'zh',
  chi: 'zh',
  rus: 'ru',
  ara: 'ar',
  hin: 'hi',
  pol: 'pl',
  swe: 'sv',
  tur: 'tr',
  ukr: 'uk',
  heb: 'he',
  ind: 'id',
  vie: 'vi',
  tha: 'th',
  ell: 'el',
  gre: 'el',
  ces: 'cs',
  cze: 'cs',
  dan: 'da',
  fin: 'fi',
  nor: 'no',
  nob: 'no',
  ron: 'ro',
  rum: 'ro',
  hun: 'hu',
};

/** Words a file adds to a caption track's name that tell the viewer nothing about what to pick. */
const CAPTION_NOISE =
  /\b(auto[- ]?generated|transcribed|transcription|transcript|subtitles?|closed captions?|captions?|cc|sdh|forced)\b/gi;

function trackKey(track: CaptionTrack | null | undefined, index: number): string {
  if (!track) return 'off';
  return `${index}:${track.id ?? ''}:${track.language ?? ''}:${track.label ?? ''}`;
}

/**
 * Two tracks the engine itself cannot tell apart: neither has an id, and they carry the same
 * language and the same name. An iPhone lists a file's caption track twice this way (once as
 * itself, once as its "forced only" twin) and picks by language and name, so choosing either
 * shows the same captions.
 */
function sameTrackToTheEngine(a: CaptionTrack, b: CaptionTrack): boolean {
  if (a.id != null || b.id != null) return false;
  if (!a.language || !b.language) return false;
  return a.language === b.language && (a.label ?? '') === (b.label ?? '');
}

/**
 * A "forced" track holds only the lines a film shows to everyone (a sign, a few words in another
 * language). An iPhone lists one beside every caption track of a file ("English Forced"), and
 * for most files it is empty: choosing it shows nothing.
 */
function isForcedOnly(track: CaptionTrack): boolean {
  return /\bforced\b/i.test(String(track.label ?? ''));
}

function sameLanguage(a: CaptionTrack, b: CaptionTrack): boolean {
  return !!a.language && !!b.language && a.language.toLowerCase() === b.language.toLowerCase();
}

type TrackFacts = { lang: string; region: string; plain: string };

/** What a track says about itself: its language, its region, and its own name with the noise taken out. */
function trackFacts(track: CaptionTrack): TrackFacts {
  const plain = String(track.label ?? '')
    .replace(CAPTION_NOISE, ' ')
    .replace(/\(\s*\)|\[\s*\]/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/^[\s,:;–-]+|[\s,:;–-]+$/g, '');
  const parts = String(track.language ?? '')
    .trim()
    .split(/[-_]/)
    .filter(Boolean);
  let lang = (parts[0] ?? '').toLowerCase();
  lang = THREE_LETTER[lang] ?? lang;
  // "und" is a file saying it does not know.
  if (!/^[a-z]{2,3}$/.test(lang) || lang === 'und') lang = '';
  const rest = parts.slice(1);
  let region = (rest.find((p) => /^([A-Za-z]{2}|\d{3})$/.test(p)) ?? '').toUpperCase();
  // Chinese is told apart by its script (Hans, Hant) rather than by a country.
  if (!region) {
    const script = rest.find((p) => /^[A-Za-z]{4}$/.test(p)) ?? '';
    region = script ? script.charAt(0).toUpperCase() + script.slice(1).toLowerCase() : '';
  }
  if (!lang) {
    for (const [code, name] of Object.entries(LANGUAGE_NAMES)) {
      if (new RegExp(`\\b${name}\\b`, 'i').test(plain)) {
        lang = code;
        break;
      }
    }
  }
  if (!region) region = (/\(([A-Za-z]{2,3})\)/.exec(plain)?.[1] ?? '').toUpperCase();
  return { lang, region, plain };
}

/**
 * Names for every caption track of a file: the short form for the button and the name for the
 * list. A language is written once ("EN", "English"); the region is added only when two tracks
 * share a language ("EN-US" and "EN-GB"), and words such as "transcribed" never appear.
 */
export function captionNames(
  tracks: readonly CaptionTrack[] | null | undefined,
): { label: string; short: string }[] {
  const list = Array.isArray(tracks) ? tracks.filter(Boolean) : [];
  const facts = list.map((t) => trackFacts(t));
  const perLanguage = new Map<string, number>();
  for (const f of facts) if (f.lang) perLanguage.set(f.lang, (perLanguage.get(f.lang) ?? 0) + 1);
  const named = facts.map((f, i) => {
    if (!f.lang) {
      return { label: f.plain || `Captions ${i + 1}`, short: f.plain ? f.plain.slice(0, 10).trim() : `CC ${i + 1}` };
    }
    const code = f.lang.toUpperCase();
    const name = LANGUAGE_NAMES[f.lang] ?? code;
    const shared = (perLanguage.get(f.lang) ?? 0) > 1 && !!f.region;
    return {
      label: shared ? `${name} (${f.region})` : name,
      short: shared ? `${code}-${f.region}` : code,
    };
  });
  // Two tracks that still read the same are numbered, so no two lines of the list are alike.
  const seen = new Map<string, number>();
  return named.map((n) => {
    const count = (seen.get(n.label) ?? 0) + 1;
    seen.set(n.label, count);
    return count === 1 ? n : { label: `${n.label} ${count}`, short: `${n.short} ${count}` };
  });
}

/**
 * The caption list: "Off" first, then every track in the file, each once. Empty when the file
 * has none. `index` is -1 for Off, else the track's place in `tracks`.
 */
export function captionChoices(
  tracks: readonly CaptionTrack[] | null | undefined,
  current: CaptionTrack | null | undefined,
): CaptionChoice[] {
  const list = Array.isArray(tracks) ? tracks.filter(Boolean) : [];
  if (list.length === 0) return [];
  const currentIndex = current
    ? list.findIndex(
        (t) =>
          (t.id != null && t.id === current.id) ||
          (t.id == null && t.language === current.language && t.label === current.label),
      )
    : -1;
  // A twin, or the "forced" companion of a full track, is offered as the track it belongs to, so
  // the list shows each set of captions once.
  const first = list.map((t, i) => {
    const earlier = list.findIndex((other) => sameTrackToTheEngine(other, t));
    if (earlier >= 0 && earlier < i) return earlier;
    if (isForcedOnly(t)) {
      const full = list.findIndex((other) => !isForcedOnly(other) && sameLanguage(other, t));
      if (full >= 0) return full;
    }
    return i;
  });
  const shownIndex = currentIndex >= 0 ? (first[currentIndex] ?? currentIndex) : -1;
  const kept = list.map((t, i) => ({ t, i })).filter(({ i }) => first[i] === i);
  const names = captionNames(kept.map(({ t }) => t));
  return [
    { key: 'off', label: 'Off', short: 'Off', index: -1, selected: shownIndex < 0 },
    ...kept.map(({ t, i }, place) => ({
      key: trackKey(t, i),
      label: names[place]?.label ?? `Captions ${place + 1}`,
      short: names[place]?.short ?? `CC ${place + 1}`,
      index: i,
      selected: i === shownIndex,
    })),
  ];
}

/**
 * The Captions line of the menu: a switch, and the language beside it.
 * `remembered` is the track last shown for this file (-1 when none yet), so switching captions
 * off and on again comes back to the same language.
 */
export function captionLine(
  choices: readonly CaptionChoice[] | null | undefined,
  remembered: number,
): { available: boolean; on: boolean; shown: CaptionChoice | null; tracks: CaptionChoice[] } {
  const tracks = (choices ?? []).filter((c) => c.index >= 0);
  const selected = tracks.find((c) => c.selected) ?? null;
  const shown = selected ?? tracks.find((c) => c.index === remembered) ?? tracks[0] ?? null;
  return { available: tracks.length > 0, on: !!selected, shown, tracks };
}

/** What the Captions switch chooses: off is -1; on is the language beside the switch. */
export function captionSwitchTarget(
  choices: readonly CaptionChoice[] | null | undefined,
  on: boolean,
  remembered: number,
): number {
  if (!on) return -1;
  return captionLine(choices, remembered).shown?.index ?? -1;
}


// ---------------------------------------------------------------------------
// Controls on screen
// ---------------------------------------------------------------------------

/** How long the controls stay up over a playing video with nobody touching them. */
export const CONTROLS_HIDE_MS = 3500;

/**
 * Should the controls hide by themselves? Only over a video that is playing, and never while the
 * menu is open or a finger is on the bar. Audio has no picture to uncover.
 */
export function controlsMayHide(s: {
  kind: PlayerKind;
  playing: boolean;
  menuOpen: boolean;
  scrubbing: boolean;
  failed: boolean;
}): boolean {
  return s.kind === 'video' && s.playing && !s.menuOpen && !s.scrubbing && !s.failed;
}

/**
 * Must the controls be on screen? Whenever there is something to play and it is not playing, and
 * while the menu is open or a finger is on the bar. Over a still picture the user decides.
 */
export function controlsPinned(s: {
  kind: PlayerKind;
  playing: boolean;
  menuOpen: boolean;
  scrubbing: boolean;
  failed: boolean;
}): boolean {
  if (s.kind === 'image') return s.menuOpen;
  return !controlsMayHide(s);
}

/**
 * A touch on the picture: bring the controls up, or put them away if they are up and it is
 * playing. Over a still picture a touch simply shows or hides them.
 */
export function controlsAfterTap(visible: boolean, playing: boolean, kind: PlayerKind = 'video'): boolean {
  if (kind === 'image') return !visible;
  if (!visible) return true;
  return !playing;
}

/** Run one call on a player that may already have been closed. Never throws. */
export function safely<T>(run: () => T, fallback: T): T {
  try {
    return run();
  } catch {
    return fallback;
  }
}

// ---------------------------------------------------------------------------
// One set of controls for every engine
// ---------------------------------------------------------------------------

export type EngineReading = { position: number; duration: number; playing: boolean; failed: boolean };

export const EMPTY_READING: EngineReading = { position: 0, duration: 0, playing: false, failed: false };

/**
 * What the player needs from whatever plays the file. Video and audio, iPhone and Android, each
 * supply these few calls; every button goes through the functions below and nowhere else, so a
 * rule fixed here is fixed for all four.
 */
export type MediaEngine = {
  play(): void;
  pause(): void;
  seekTo(seconds: number): void;
  setRate(rate: number): void;
  setLoop(loop: boolean): void;
  read(): EngineReading;
  captions(): { tracks: readonly CaptionTrack[]; current: CaptionTrack | null };
  /** `index` as in `captionChoices`: -1 turns captions off. */
  chooseCaption(index: number): void;
};

/** The engine's state, with anything unreadable turned into a plain zero or false. */
export function readEngine(engine: MediaEngine | null | undefined): EngineReading {
  if (!engine) return { ...EMPTY_READING };
  const raw = safely(() => engine.read(), null as EngineReading | null);
  if (!raw) return { ...EMPTY_READING };
  return {
    position: Math.max(0, finite(raw.position)),
    duration: Math.max(0, finite(raw.duration)),
    playing: raw.playing === true,
    failed: raw.failed === true,
  };
}

/** The Play / Pause button. Returns whether it is playing afterwards. */
export function pressPlayPause(engine: MediaEngine | null | undefined): boolean {
  if (!engine) return false;
  const now = readEngine(engine);
  if (now.playing) {
    safely(() => engine.pause(), undefined);
    return false;
  }
  if (playStartsOver(now.position, now.duration)) safely(() => engine.seekTo(0), undefined);
  return safely(() => {
    engine.play();
    return true;
  }, false);
}

/** A jump button. Returns where it landed. */
export function pressJump(engine: MediaEngine | null | undefined, delta: number): number {
  if (!engine) return 0;
  const now = readEngine(engine);
  const target = jumpTarget(now.position, delta, now.duration);
  safely(() => engine.seekTo(target), undefined);
  return target;
}

/** A touch on the bar. Returns where it landed, or `null` when it could not be placed. */
export function pressBar(engine: MediaEngine | null | undefined, x: number, width: number): number | null {
  if (!engine) return null;
  const target = barTarget(x, width, readEngine(engine).duration);
  if (target === null) return null;
  safely(() => engine.seekTo(target), undefined);
  return target;
}

/** Put Loop and Speed onto an engine. Called for every new file, so Loop carries over. */
export function applyPlayback(
  engine: MediaEngine | null | undefined,
  playback: { loop: boolean; speed: number },
): void {
  if (!engine) return;
  safely(() => engine.setLoop(playback.loop === true), undefined);
  // On iPhone, giving a paused player a speed starts it. Choosing a speed is not pressing play:
  // a player that was paused is paused again.
  const wasPlaying = readEngine(engine).playing;
  safely(() => engine.setRate(validSpeed(playback.speed)), undefined);
  if (!wasPlaying) safely(() => engine.pause(), undefined);
}

/** The caption list of an engine; empty when it has none or cannot say. */
export function engineCaptionChoices(engine: MediaEngine | null | undefined): CaptionChoice[] {
  if (!engine) return [];
  const got = safely(() => engine.captions(), null as ReturnType<MediaEngine['captions']> | null);
  if (!got) return [];
  return captionChoices(got.tracks, got.current);
}

// ---------------------------------------------------------------------------
// The options menu
// ---------------------------------------------------------------------------

export type MenuLine = 'speed' | 'loop' | 'orientation' | 'captions';

/** The lines of the menu, top to bottom. Sound has no picture to turn and no captions to show. */
export function menuLines(kind: PlayerKind): MenuLine[] {
  if (kind === 'video') return ['speed', 'loop', 'orientation', 'captions'];
  if (kind === 'audio') return ['speed', 'loop'];
  return [];
}

export const MENU_LINE_HEIGHT = 44;
export const MENU_PADDING = 6;
export const MENU_MIN_WIDTH = 240;
export const MENU_MAX_WIDTH = 280;

/**
 * How big the menu is: about half the screen across, never narrower than its widest line and
 * never wider than it needs; as tall as its lines and no taller.
 */
export function menuBox(screen: { width: number; height: number }, lines: number): { width: number; height: number } {
  const half = Math.round(Math.max(0, finite(screen.width)) / 2);
  const room = Math.max(0, finite(screen.width) - 24);
  const width = Math.min(Math.max(half, MENU_MIN_WIDTH), MENU_MAX_WIDTH, room || MENU_MIN_WIDTH);
  const count = Math.max(0, Math.floor(finite(lines)));
  return { width, height: count * MENU_LINE_HEIGHT + MENU_PADDING * 2 };
}

// ---------------------------------------------------------------------------
// Swipes
// ---------------------------------------------------------------------------

/** Up puts the player away. Left and right move through the list the host gave the player. */
export type SwipeAxis = 'horizontal' | 'vertical';
export type SwipeAction = 'close' | 'next' | 'previous';
export type SwipeRoom = { width: number; height: number; hasNext: boolean; hasPrevious: boolean };

/** How far a finger travels before it counts as a swipe and not a tap. */
export const SWIPE_START = 12;

/**
 * Which way a moving finger is going, decided once at the start of the swipe. `null` while it
 * has not moved far enough, and for a downward pull, which does nothing.
 */
export function swipeAxis(dx: number, dy: number): SwipeAxis | null {
  const across = Math.abs(finite(dx));
  const along = Math.abs(finite(dy));
  if (Math.max(across, along) < SWIPE_START) return null;
  if (across >= along) return 'horizontal';
  return finite(dy) < 0 ? 'vertical' : null;
}

/**
 * Where the player sits under the finger. It follows a swipe towards something; towards an end
 * of the list it drags behind, so the user can feel there is nothing that way.
 */
export function swipeOffset(
  move: { axis: SwipeAxis | null; dx: number; dy: number },
  room: SwipeRoom,
): { x: number; y: number } {
  if (move.axis === 'horizontal') {
    const dx = finite(move.dx);
    const open = dx < 0 ? room.hasNext : room.hasPrevious;
    return { x: open ? dx : dx * 0.25, y: 0 };
  }
  if (move.axis === 'vertical') return { x: 0, y: Math.min(0, finite(move.dy)) };
  return { x: 0, y: 0 };
}

/**
 * What a swipe did when the finger lifted: far enough, or a quick flick, in a direction that
 * leads somewhere. Anything else is `null` and the player settles back.
 * Speeds are in points per millisecond, as React Native reports them.
 */
export function swipeAction(
  move: { axis: SwipeAxis | null; dx: number; dy: number; vx: number; vy: number },
  room: SwipeRoom,
): SwipeAction | null {
  const dx = finite(move.dx);
  const dy = finite(move.dy);
  if (move.axis === 'horizontal') {
    const far = Math.min(120, Math.max(48, finite(room.width) * 0.28));
    const flick = Math.abs(finite(move.vx)) >= 0.45 && Math.abs(dx) >= 36 && Math.sign(move.vx) === Math.sign(dx);
    if (Math.abs(dx) < far && !flick) return null;
    if (dx < 0) return room.hasNext ? 'next' : null;
    return room.hasPrevious ? 'previous' : null;
  }
  if (move.axis === 'vertical') {
    const far = Math.min(140, Math.max(60, finite(room.height) * 0.18));
    const flick = finite(move.vy) <= -0.45 && dy <= -36;
    return dy <= -far || flick ? 'close' : null;
  }
  return null;
}

/** The files either side of the one on screen, in the host's order. The list has two ends. */
export function playlistNeighbours<T>(
  items: readonly T[] | null | undefined,
  isCurrent: (item: T) => boolean,
): { previous: T | null; next: T | null } {
  const list = Array.isArray(items) ? items : [];
  const at = list.findIndex((item) => isCurrent(item));
  if (at < 0) return { previous: null, next: null };
  return { previous: list[at - 1] ?? null, next: list[at + 1] ?? null };
}
